import { useEffect, useState, useCallback, type FormEvent, type ReactNode } from 'react';
import { LayoutDashboard, CalendarDays, BedDouble, Users, Sparkles, Wallet, Settings, Plus, Search, ChevronRight, ChevronLeft, ArrowUpRight, ArrowDownRight, LogIn, LogOut, Download, Building2, RefreshCw, CircleHelp, Check, Clock3, Wrench, X, SlidersHorizontal, ShieldCheck, ArrowRight, ReceiptText, CircleCheck, PanelLeft, Loader2, Tags, Pencil, ArrowLeftRight, Printer, FileText, IdCard, CreditCard, Trash2, TriangleAlert } from 'lucide-react';
import { SidebarProvider, Sidebar, SidebarHeader, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupLabel, SidebarMenu, SidebarMenuItem, SidebarMenuButton, SidebarInset, SidebarTrigger, useSidebar } from '@/components/ui/sidebar';
